import shutil
from pathlib import Path

RULES = {".pdf": "Documents", ".txt": "Documents", ".jpg": "Images", ".png": "Images", ".mp3": "Music"}

def organise(folder: Path, apply: bool = False) -> list[tuple[str, str]]:
    """Plan (and with apply=True, perform) moves of loose files into category folders."""
    plan = []
    for path in sorted(folder.iterdir()):
        if path.is_dir():
            continue
        category = RULES.get(path.suffix.lower(), "Other")
        plan.append((path.name, category))
        if apply:
            (folder / category).mkdir(exist_ok=True)
            shutil.move(path, folder / category / path.name)
    return plan

for name, category in organise(Path("inbox")):
    print(f"{name} -> {category}")

