import contextlib, io
def parse(argv):
    with contextlib.redirect_stderr(io.StringIO()) as err:
        try:
            return build_parser().parse_args(argv)
        except SystemExit:
            raise AssertionError("argparse rejected " + " ".join(argv) + ". It said: " + err.getvalue().strip().splitlines()[-1])
p = build_parser()
a = parse(["photos", "--prefix", "goa_"])
assert (a.folder, a.prefix, a.ext, a.apply, a.start) == ("photos", "goa_", ".jpg", False, 1), "With only a folder and --prefix, expected folder='photos', prefix='goa_', ext='.jpg', apply=False, start=1. Got " + str(vars(a))
a = parse(["photos", "--prefix", "trip_", "--ext", ".png", "--apply", "--start", "10"])
assert a.apply is True and a.ext == ".png", "--apply should set apply to True and --ext .png should change ext."
assert a.start == 10, "--start 10 should give the number 10, not the text '10'. Use type=int."
with contextlib.redirect_stderr(io.StringIO()):
    try:
        p.parse_args(["photos"])
    except SystemExit:
        pass
    else:
        raise AssertionError("Without --prefix argparse should stop with an error. Add required=True to --prefix.")
